const saveAttackHistoryCompleteBase=saveAttackHistory;
saveAttackHistory=function(){const guardian=guardianContext(),djemSo=allResolved(defender).some(x=>x.def.id==='maitrise-du-djem-so')&&attackType()==='melee'&&attackState.roll.blank>0;saveAttackHistoryCompleteBase();const defenderStats=certifiedUnitStats(defender),defenderState=stateFor(defender);if(defenderStats){const capped=Math.min(defenderStats.totalWounds,defenderState.wounds);unitStates[defender.id]={...defenderState,wounds:capped,suppression:capped>=defenderStats.totalWounds?0:defenderState.suppression}}if(guardian?.candidate&&guardian.result.wounds>0)persistWounds(guardian.candidate,guardian.result.wounds);if(djemSo)persistWounds(attacker,1);localStorage.setItem(unitStateKey,JSON.stringify(unitStates))};
function casualtyModelsPanel(entry,newWounds){const allocation=casualtyResult(entry,newWounds);if(!allocation)return'';return `<div class="casualty-models" aria-label="Répartition des blessures">${allocation.models.map((model,index)=>`<span class="${model.defeated?'defeated':''}"><small>${displayName(model.source)} ${index+1}</small><b>${model.wounds}/${model.maxWounds}${model.defeated?' ☠':''}</b></span>`).join('')}</div>`}
const suppressionScreenCasualtiesBase=suppressionScreen;
suppressionScreen=function(){const html=suppressionScreenCasualtiesBase(),result=defenseResult().result,panel=casualtyModelsPanel(defender,result.wounds);return panel?html.replace(/(<div class="casualty-summary[\s\S]*?<\/div>)/,'$1'+panel):html};
const resolveScreenCompletionBase=resolveScreen;
resolveScreen=function(){resolveScreenCompletionBase();const next=$('#nextAttack');if(next&&attackStep===5)next.textContent=defenseResult().result.wounds?'Appliquer les blessures et terminer':'Terminer l’attaque'};
const decorateDiceJourneyBase=decorateResolveScreen;
decorateResolveScreen=function(){decorateDiceJourneyBase();const journey=root.querySelector('.resolve-center .dice-journey'),journal=root.querySelector('.resolve-center .resolution-log'),rules=root.querySelector('.resolve-center .rules-panel');if(journey){if(journal)journal.before(journey);else if(rules)rules.before(journey);else root.querySelector('.resolve-center')?.append(journey)}};
let postRallyMoves=new Set,rallyDemoralizeSpent={};
function postRallyPanel(entry){if(!ralliedUnits.has(entry.id))return'';const state=stateFor(entry),stats=certifiedUnitStats(entry),morale=stats?engine.moraleState({currentSuppression:state.suppression,courage:stats.courage}):null,eligible=morale?.suppressed&&!morale?.panicRisk&&!postRallyMoves.has(entry.id),intrepid=allResolved(entry).some(x=>x.def.id==='intrepide'),constrainers=entries.filter(candidate=>candidate.army===entry.army&&candidate.id!==entry.id&&allResolved(candidate).some(x=>x.def.id==='contrainte')),demoralize=keywordValue(entry,'demoraliser-x'),spent=rallyDemoralizeSpent[entry.id]||0,targets=entries.filter(candidate=>candidate.army!==entry.army&&!defeated(candidate));if(!intrepid&&!constrainers.length&&!demoralize)return'';return `<section class="post-rally-panel"><strong>EFFETS APRÈS RALLIEMENT</strong>${intrepid?`<div><b>INTRÉPIDE</b><small>Si l’unité est démoralisée mais pas paniquée, elle peut gagner 1 suppression pour effectuer un déplacement gratuit.</small><button class="secondary" data-post-rally-move="${entry.id}" ${eligible?'':'disabled'}>${postRallyMoves.has(entry.id)?'Déplacement gratuit enregistré':'Gagner 1 suppression et se déplacer'}</button></div>`:''}${constrainers.length&&!intrepid?`<div><b>CONTRAINTE DISPONIBLE</b><small>Vérifiez la portée 2, le rang/type demandé et que l’unité est un soldat non-droïde. Si elle est démoralisée mais pas paniquée, elle peut gagner 1 suppression pour se déplacer gratuitement.</small><button class="secondary" data-post-rally-move="${entry.id}" ${eligible?'':'disabled'}>${postRallyMoves.has(entry.id)?'Déplacement gratuit enregistré':'Conditions vérifiées : appliquer'}</button></div>`:''}${demoralize?`<div><b>DÉMORALISER ${demoralize}</b><small>Après le ralliement, attribuez jusqu’à ${demoralize} suppression(s) à des unités ennemies à portée 2. ${spent}/${demoralize} attribuée(s).</small><div class="demoralize-targets">${targets.map(target=>`<button class="secondary" data-demoralize-target="${target.id}" data-source="${entry.id}" ${spent>=demoralize?'disabled':''}>+1 ${entryName(target)}</button>`).join('')||'<em>Aucune cible disponible</em>'}</div></div>`:''}</section>`}
function bindPostRally(entry,role){const move=root.querySelector(`[data-post-rally-move="${entry.id}"]`);if(move)move.onclick=()=>{const state=stateFor(entry);unitStates[entry.id]={...state,suppression:state.suppression+1};postRallyMoves.add(entry.id);localStorage.setItem(unitStateKey,JSON.stringify(unitStates));overview(entry,role)};root.querySelectorAll(`[data-demoralize-target][data-source="${entry.id}"]`).forEach(button=>button.onclick=()=>{const max=keywordValue(entry,'demoraliser-x'),spent=rallyDemoralizeSpent[entry.id]||0;if(spent>=max)return;const target=entries.find(candidate=>candidate.id===button.dataset.demoralizeTarget);if(!target||moraleImmune(target))return;const state=stateFor(target);unitStates[target.id]={...state,suppression:state.suppression+1};rallyDemoralizeSpent[entry.id]=spent+1;localStorage.setItem(unitStateKey,JSON.stringify(unitStates));overview(entry,role)})}
const overviewPostRallyBase=overview;
overview=function(entry,role){overviewPostRallyBase(entry,role);if(role==='attack'&&ralliedUnits.has(entry.id)){const panel=document.createElement('div');panel.innerHTML=postRallyPanel(entry);const content=panel.firstElementChild;if(content){const anchor=root.querySelector('.overview .upgrade-gallery')||root.querySelector('.overview .columns');anchor?.before(content);bindPostRally(entry,role)}}};
document.addEventListener('click',event=>{const armyButton=event.target.closest?.('[data-army]');if(armyButton&&stage===1)applyFactionTheme(factionThemeForArmy(armyButton.dataset.army));const unitButton=event.target.closest?.('.unit-tile[data-id]');if(unitButton&&stage===1){const entry=entries.find(candidate=>candidate.id===unitButton.dataset.id);if(entry)applyFactionTheme(factionThemeForArmy(entry.army));requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'instant'}))}},true);
applyFactionTheme('rebel');
$('#restart').onclick=()=>{attacker=null;defender=null;selectedArmy='p1';stage=1;applyFactionTheme('rebel');pick('attacker')};pick('attacker');
